"use client";
import {ChangeEvent,FormEvent,useEffect,useRef,useState} from "react";
const API=process.env.NEXT_PUBLIC_API_BASE||"";
export {StyleLibraryPanel,VoiceLibraryPanel};
const LOCAL_PREFERENCES_KEY="whiteboard-maker:local-preferences:v1";
type Config={api_key:string;base_url:string;text_model:string;image_model:string;image_base_url:string;image_api_key:string;tts_url:string;tts_url_2:string;tts_mode:string;output_dir:string;has_api_key?:boolean;has_image_api_key?:boolean};
type TimingEntry={label:string;seconds:number;running?:boolean};
type Job={id:string;status:"queued"|"running"|"done"|"error"|"cancelled";stage:string;progress:number;client_ip?:string;queue_ahead?:number;created_at?:number;task_name?:string;pen_text?:string;style?:string;stroke_detail?:string;job_type?:string;rerender_of?:string;can_rerender?:boolean;can_retry?:boolean;can_cancel?:boolean;model_retry_count?:number;manual_retry_count?:number;result_url?:string;output_path?:string|null;error?:string;duration?:number;scenes?:number;boards?:number;image_count?:number;total_elapsed?:number;current_elapsed?:number;resume_count?:number;checkpoint?:string;timings?:Record<string,TimingEntry>};
type CharacterReference={id:string;name:string;description:string;files:File[]};
type InputAsset={name:string;url:string;content_type:string};
type JobParameters={copy:string;reference_mode:"standard"|"custom"|"infographic";style:string;aspect_ratio:string;scenes_per_image:number;task_name:string;pen_text:string;include_key_text:boolean;include_subtitles:boolean;stroke_detail:string;reference:InputAsset|null;style_reference:InputAsset|null;characters:{name:string;description:string;images:InputAsset[]}[]};
type StyleOption={id:string;name:string;image:string;desc:string;recipe?:string;aliases?:string[];badge?:string;builtin?:boolean;custom?:boolean};
type GalleryItem={name:string;page:number;url:string;size:number;prompt?:string;scene_numbers?:number[]};
type AssetPreview={src:string;label:string};
type Voice={id:string;name:string;filename:string;content_type?:string;size?:number;created_at?:number};
type ServiceHealth={queues:{voice:{concurrency:number;waiting:number;nodes:{index:number;url:string;active:boolean;job_id?:string|null}[]};model:{concurrency:number;waiting:number};render:{concurrency:string;active:number}}};
const defaults:Config={api_key:"",base_url:"https://api.openlux.ai/v1",text_model:"gpt-5",image_model:"gpt-image-2",image_base_url:"",image_api_key:"",tts_url:"http://127.0.0.1:7860",tts_url_2:"",tts_mode:"gradio",output_dir:""};
const assetUrl=(path:string)=>path.startsWith("http://")||path.startsWith("https://")||path.startsWith("/styles/")?path:API?`${API}${path}`:path;
const countScriptUnits=(text:string)=>Math.max(1,(text.match(/[^。！？!?；;\n]+[。！？!?；;]?/g)||[]).filter(item=>item.trim()).length);
const estimateMinutes=(text:string)=>Math.max(1/8,text.trim().length/250);
const estimateSceneCount=(text:string)=>Math.max(1,Math.min(countScriptUnits(text),Math.max(1,Math.floor(estimateMinutes(text)*8))));
const builtinStyleOptions:StyleOption[]=[
 {id:"builtin-minimal-whiteboard",name:"极简粗线简笔白板风",image:"/styles/minimal-whiteboard.webp",desc:"粗黑线 · 少量配色 · 清爽留白",builtin:true},
 {id:"builtin-business-doodle",name:"极简商务涂鸦风",image:"/styles/business-doodle.webp",desc:"几何图表 · 蓝绿配色 · 专业克制",builtin:true},
 {id:"builtin-warm-pencil",name:"暖米黄素描白板风",image:"/styles/warm-pencil.webp",desc:"铅笔排线 · 纸张质感 · 温暖细腻",builtin:true},
 {id:"builtin-guofeng-flat",name:"粗线扁平国风卡通",image:"/styles/guofeng-flat.webp",desc:"朱红玉绿 · 国风纹样 · 生动平涂",builtin:true},
 {id:"builtin-viral-pop",name:"爆款高热吸睛风",image:"/styles/viral-pop.webp",desc:"高饱和 · 强对比 · 短视频冲击力",badge:"热门",builtin:true},
 {id:"builtin-black-gold-tech",name:"黑金科技发布会风",image:"/styles/black-gold-tech.webp",desc:"黑金光效 · 科技舞台 · 高级权威",builtin:true},
 {id:"builtin-healing-journal",name:"清新治愈手账风",image:"/styles/healing-journal.webp",desc:"柔和水彩 · 治愈配色 · 生活手账",builtin:true},
 {id:"builtin-retro-collage",name:"复古报纸拼贴风",image:"/styles/retro-collage.webp",desc:"撕纸拼贴 · 半色调 · 编辑视觉",builtin:true},
 {id:"builtin-paper-metaphor",name:"纸感隐喻拼贴风",image:"/styles/paper-metaphor.png",desc:"手工剪纸 · 观点隐喻 · 高级克制",badge:"新增",builtin:true},
 {id:"builtin-oil-visual",name:"漫画墨线解释风",image:"/styles/oil-visual.png",desc:"漫画墨线 · 半调网点 · 概念机制",badge:"新增",builtin:true},
 {id:"builtin-clay-3d",name:"3D黏土趣味风",image:"/styles/clay-3d.webp",desc:"黏土材质 · 玩具比例 · 温暖可爱",builtin:true},
 {id:"builtin-cyber-neon",name:"赛博霓虹漫画风",image:"/styles/cyber-neon.webp",desc:"霓虹青紫 · 漫画速度线 · 未来感",builtin:true},
];
builtinStyleOptions.forEach(item=>{item.custom=true});
const styleOptions:StyleOption[]=builtinStyleOptions.map(item=>({...item,custom:true}));
const aspectRatioOptions=[
 {value:"16:9",label:"16:9 横屏",note:"课程、讲解、电脑端"},
 {value:"9:16",label:"9:16 竖屏",note:"短视频、手机全屏"},
 {value:"1:1",label:"1:1 方形",note:"社交平台、信息卡"},
];
function StyleLibraryPanel({styles,onRefresh,onSelect}:{styles:StyleOption[];onRefresh:()=>Promise<void>;onSelect:(name:string)=>void}){
 const[name,setName]=useState("");const[description,setDescription]=useState("");const[recipe,setRecipe]=useState("");const[image,setImage]=useState<File|null>(null);const[busy,setBusy]=useState(false);const[message,setMessage]=useState("");
 const add=async()=>{if(name.trim().length<2)return setMessage("请输入至少 2 个字的风格名称");if(recipe.trim().length<10)return setMessage("请填写至少 10 个字的画面风格配方");setBusy(true);setMessage("");try{const body=new FormData();body.append("name",name);body.append("description",description);body.append("recipe",recipe);if(image)body.append("image",image);const response=await fetch(`${API}/api/styles`,{method:"POST",body});const data=await response.json();if(!response.ok)throw new Error(data.detail||"新增画面风格失败");setName("");setDescription("");setRecipe("");setImage(null);setMessage(`已新增画面风格“${data.name}”`);await onRefresh()}catch(err){setMessage(err instanceof Error?err.message:"新增画面风格失败")}finally{setBusy(false)}};
 const edit=async(style:StyleOption)=>{const nextName=window.prompt("风格名称",style.name)?.trim();if(!nextName)return;const nextDescription=window.prompt("风格简介",style.desc)?.trim()??style.desc;const nextRecipe=window.prompt("生成配方（描述背景、线条、材质、配色和构图要求）",style.recipe||"")?.trim();if(!nextRecipe)return;setBusy(true);setMessage("");try{const response=await fetch(`${API}/api/styles/${style.id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:nextName,description:nextDescription,recipe:nextRecipe})});const data=await response.json();if(!response.ok)throw new Error(data.detail||"编辑画面风格失败");setMessage(`已更新画面风格“${data.name}”`);await onRefresh()}catch(err){setMessage(err instanceof Error?err.message:"编辑画面风格失败")}finally{setBusy(false)}};
 const remove=async(style:StyleOption)=>{if(style.builtin||!window.confirm(`确定删除画面风格“${style.name}”吗？`))return;setBusy(true);setMessage("");try{const response=await fetch(`${API}/api/styles/${style.id}`,{method:"DELETE"});const data=await response.json();if(!response.ok)throw new Error(data.detail||"删除画面风格失败");setMessage(`已删除画面风格“${style.name}”`);await onRefresh()}catch(err){setMessage(err instanceof Error?err.message:"删除画面风格失败")}finally{setBusy(false)}};
 return <section className="settings panel styleLibraryPanel"><Title n="03" title="画面风格库" note="内置风格可编辑但不可删除，自定义风格只保存在本机"/><div className="styleLibraryAdd"><label>风格名称<input maxLength={40} value={name} onChange={event=>setName(event.target.value)} placeholder="例如：复古胶片科普风"/></label><label>风格简介<input maxLength={100} value={description} onChange={event=>setDescription(event.target.value)} placeholder="例如：颗粒胶片 · 暖色调 · 纪录片感"/></label><label>生成配方<textarea value={recipe} onChange={event=>setRecipe(event.target.value)} placeholder="描述背景、线条、材质、配色、构图和禁止项，生成时会原样提供给图片模型"/></label><label>预览图<input type="file" accept="image/png,image/jpeg,image/webp" onChange={event=>setImage(event.target.files?.[0]||null)}/><small>{image?image.name:"可选；不上传时使用默认白板预览图"}</small></label><button type="button" className="primary small" onClick={add} disabled={busy}>{busy?"处理中…":"新增画面风格"}</button></div>{styles.length?<div className="customStyleList">{styles.map(style=><article key={style.id}><img src={style.image} alt=""/><div><strong>{style.name}</strong><span>{style.builtin?"内置 · ":""}{style.desc}</span></div><div><button type="button" className="secondary small" onClick={()=>onSelect(style.name)}>使用</button><details className="styleDetail"><summary>查看详情</summary><div><p><strong>类型</strong>{style.builtin?"内置风格":"自定义风格"}</p><p><strong>简介</strong>{style.desc||"暂无简介"}</p><p><strong>生成配方</strong>{style.recipe||"暂无配方，请刷新后端服务获取完整配置。"}</p></div></details><button type="button" className="editHistory" onClick={()=>edit(style)} disabled={busy}>编辑</button>{!style.builtin&&<button type="button" className="deleteHistory" onClick={()=>remove(style)} disabled={busy}>删除</button>}</div></article>)}</div>:<p className="styleLibraryEmpty">还没有可管理的画面风格。</p>}{message&&<p className={`message ${message.startsWith("已")?"successMessage":""}`}>{message}</p>}</section>}
export default function Home(){
 const[,setStyleRevision]=useState(0);
 const[pageMode,setPageMode]=useState<"standard"|"custom"|"infographic">("standard");
 const[styleReference,setStyleReference]=useState<File|null>(null);
 const[characters,setCharacters]=useState<CharacterReference[]>([{id:"character-1",name:"人物 1",description:"",files:[]}]);
 const[voices,setVoices]=useState<Voice[]>([]);const[selectedVoiceId,setSelectedVoiceId]=useState("");const[voiceSource,setVoiceSource]=useState<"upload"|"library">("upload");const[voiceLoading,setVoiceLoading]=useState(false);
 const[sharedJob,setSharedJob]=useState<Job|null>(null);
 const[includeKeyText,setIncludeKeyText]=useState(true);const[restoringJobId,setRestoringJobId]=useState<string|null>(null);const[detailJobId,setDetailJobId]=useState<string|null>(null);const[detailJob,setDetailJob]=useState<Job|null>(null);const[detailParameters,setDetailParameters]=useState<JobParameters|null>(null);const[gallery,setGallery]=useState<GalleryItem[]>([]);const[previewImage,setPreviewImage]=useState<GalleryItem|null>(null);const[assetPreview,setAssetPreview]=useState<AssetPreview|null>(null);const[inputPreviewFile,setInputPreviewFile]=useState<File|null>(null);const[selectedGalleryPage,setSelectedGalleryPage]=useState<number|null>(null);const[promptDraft,setPromptDraft]=useState("");const[regeneratingPage,setRegeneratingPage]=useState<number|null>(null);const[detailActionMessage,setDetailActionMessage]=useState("");const[detailLoading,setDetailLoading]=useState(false);
 const[copy,setCopy]=useState("");const[reference,setReference]=useState<File|null>(null);const[style,setStyle]=useState("极简粗线简笔白板风");const[aspectRatio,setAspectRatio]=useState("16:9");const[scenesPerImage,setScenesPerImage]=useState(1);const[taskName,setTaskName]=useState("");const[penText,setPenText]=useState("");const[strokeDetail,setStrokeDetail]=useState("detailed");const[includeSubtitles,setIncludeSubtitles]=useState(true);const[preferencesLoaded,setPreferencesLoaded]=useState(false);const[settingsOpen,setSettingsOpen]=useState(false);const[config,setConfig]=useState<Config>(defaults);const[health,setHealth]=useState<ServiceHealth|null>(null);const[job,setJob]=useState<Job|null>(null);const[history,setHistory]=useState<Job[]>([]);const[message,setMessage]=useState("");const[connectionMessage,setConnectionMessage]=useState("");const[connectionOk,setConnectionOk]=useState<boolean|null>(null);const[testing,setTesting]=useState(false);const timer=useRef<ReturnType<typeof setInterval>|null>(null);
 const[historySearch,setHistorySearch]=useState("");const[historyPage,setHistoryPage]=useState(1);const[historyPages,setHistoryPages]=useState(1);const[historyTotal,setHistoryTotal]=useState(0);
 useEffect(()=>{let active=true;let reconnectTimer:ReturnType<typeof setInterval>|null=null;const reconnect=async()=>{try{const r=await fetch(`${API}/api/config`);if(!r.ok)throw new Error();const data=await r.json();if(active){setConfig(data);setMessage(current=>current==="后端尚未启动"?"":current);if(reconnectTimer){clearInterval(reconnectTimer);reconnectTimer=null}}}catch{if(active)setMessage("后端尚未启动")}};reconnect();reconnectTimer=setInterval(reconnect,3000);return()=>{active=false;if(reconnectTimer)clearInterval(reconnectTimer);if(timer.current)clearInterval(timer.current)}},[]);
 useEffect(()=>{if(window.location.hash==="#api-settings")setSettingsOpen(true)},[]);
 useEffect(()=>{try{const saved=localStorage.getItem(LOCAL_PREFERENCES_KEY);if(saved){const data=JSON.parse(saved);setPenText(String(data.pen_text||""));setStrokeDetail(["light","standard","detailed","full"].includes(data.stroke_detail)?data.stroke_detail:"detailed");setScenesPerImage(Math.max(1,Math.min(4,Number(data.scenes_per_image)||1)));setIncludeKeyText(data.include_key_text!==false);setIncludeSubtitles(data.include_subtitles!==false);if(aspectRatioOptions.some(item=>item.value===data.aspect_ratio))setAspectRatio(data.aspect_ratio);if(styleOptions.some(item=>item.name===data.style))setStyle(data.style);if(["custom","standard","infographic"].includes(data.page_mode))setPageMode(data.page_mode)}}catch{}finally{setPreferencesLoaded(true)}},[]);
 useEffect(()=>{if(!preferencesLoaded)return;const timeout=setTimeout(()=>{localStorage.setItem(LOCAL_PREFERENCES_KEY,JSON.stringify({pen_text:penText,stroke_detail:strokeDetail,scenes_per_image:scenesPerImage,include_key_text:includeKeyText,include_subtitles:includeSubtitles,style,aspect_ratio:aspectRatio,page_mode:pageMode}))},300);return()=>clearTimeout(timeout)},[penText,strokeDetail,scenesPerImage,includeKeyText,includeSubtitles,style,aspectRatio,pageMode,preferencesLoaded]);
 const loadHistory=async()=>{try{const params=new URLSearchParams({search:historySearch,page:String(historyPage),page_size:"8"});const[jobsResponse,healthResponse]=await Promise.all([fetch(`${API}/api/jobs?${params}`),fetch(`${API}/api/health`)]);if(jobsResponse.ok){const data=await jobsResponse.json();const items:Job[]=data.items||[];setHistory(items);setHistoryPages(data.pages||1);setHistoryTotal(data.total||0);if(data.page&&data.page!==historyPage)setHistoryPage(data.page);setSharedJob(items.find(item=>item.status==="running")||items.find(item=>item.status==="queued")||null)}if(healthResponse.ok)setHealth(await healthResponse.json())}catch{}};
 const loadVoices=async()=>{try{const response=await fetch(`${API}/api/voices?page_size=100`);if(!response.ok)return;const data=await response.json();const items:Voice[]=data.items||[];setVoices(items)}catch{}};
 const loadStyles=async()=>{try{const response=await fetch(`${API}/api/styles?page_size=100`);if(!response.ok)return;const data=await response.json();const items=(data.items||[]) as StyleOption[];const builtinItems=new Map(items.filter(item=>item.builtin).map(item=>[item.id,item]));const mergedBuiltins=builtinStyleOptions.map(base=>{const item=builtinItems.get(base.id);return item?{...base,name:item.name,desc:item.description||base.desc,recipe:item.recipe,aliases:item.aliases||[],builtin:true,custom:true,image:item.image_url?assetUrl(item.image_url):base.image}:base});const customItems=items.filter(item=>item.custom!==false).map(item=>({id:item.id,name:item.name,image:item.image_url?assetUrl(item.image_url):"/styles/minimal-whiteboard.webp",desc:item.description||"自定义画面风格",recipe:item.recipe,aliases:item.aliases||[],custom:true}));styleOptions.splice(0,styleOptions.length,...mergedBuiltins,...customItems);const saved=localStorage.getItem(LOCAL_PREFERENCES_KEY);const savedStyle=saved?String(JSON.parse(saved).style||""):"";const preferred=savedStyle||style;const matched=styleOptions.find(item=>item.name===preferred||item.aliases?.includes(preferred));if(matched)setStyle(matched.name);else setStyle("极简粗线简笔白板风");setStyleRevision(value=>value+1)}catch{}};
 const onFile=(e:ChangeEvent<HTMLInputElement>)=>{setReference(e.target.files?.[0]||null);setVoiceSource("upload");setSelectedVoiceId("")};
 const selectVoice=async(voiceId:string)=>{setSelectedVoiceId(voiceId);setVoiceSource("library");if(!voiceId){setReference(null);setVoiceLoading(false);return}setVoiceLoading(true);setMessage("");try{const response=await fetch(`${API}/api/voices/${voiceId}/audio`);if(!response.ok)throw new Error("无法读取音色文件");const voice=voices.find(item=>item.id===voiceId);const blob=await response.blob();setReference(new File([blob],voice?.filename||"reference.wav",{type:voice?.content_type||blob.type||"audio/wav"}))}catch(err){setReference(null);setMessage(err instanceof Error?err.message:"读取音色失败")}finally{setVoiceLoading(false)}};
 const updateCharacter=(id:string,patch:Partial<CharacterReference>)=>setCharacters(items=>items.map(item=>item.id===id?{...item,...patch}:item));
 const addCharacter=()=>setCharacters(items=>items.length>=5?items:[...items,{id:`character-${Date.now()}`,name:`人物 ${items.length+1}`,description:"",files:[]}]);
 const removeCharacter=(id:string)=>setCharacters(items=>items.length===1?items:items.filter(item=>item.id!==id));
 useEffect(()=>{loadHistory();const id=setInterval(loadHistory,2000);return()=>clearInterval(id)},[historySearch,historyPage]);
 useEffect(()=>{loadVoices()},[]);
 useEffect(()=>{loadStyles()},[]);
 useEffect(()=>{if(voiceSource==="library"&&selectedVoiceId&&!voices.some(item=>item.id===selectedVoiceId)){setSelectedVoiceId("");setReference(null)}},[voiceSource,selectedVoiceId,voices]);
 const poll=(id:string)=>{if(timer.current)clearInterval(timer.current);timer.current=setInterval(async()=>{const r=await fetch(`${API}/api/jobs/${id}`);if(!r.ok)return;const next=await r.json();setJob(next);if(["done","error","cancelled"].includes(next.status)){if(timer.current)clearInterval(timer.current);loadHistory()}},1600)};
 const create=async(e:FormEvent)=>{e.preventDefault();setMessage("");if(!reference)return setMessage("请先上传一段清晰的参考音频");if(copy.trim().length<10)return setMessage("文案至少需要 10 个字");const readyCharacters=characters.filter(item=>item.name.trim()&&item.files.length);if(pageMode==="custom"&&!styleReference)return setMessage("请上传一张画面风格参考图");if(pageMode==="custom"&&!readyCharacters.length)return setMessage("请至少添加一个带参考图片的人物");const body=new FormData();body.append("copy",copy);body.append("style",pageMode==="custom"?"自定义参考":style);body.append("aspect_ratio",aspectRatio);body.append("reference_mode",pageMode);body.append("scenes_per_image",String(pageMode==="infographic"?1:scenesPerImage));body.append("task_name",taskName);body.append("pen_text",penText);body.append("include_key_text",String(includeKeyText));body.append("stroke_detail",strokeDetail);body.append("include_subtitles",String(includeSubtitles));body.append("reference",reference);if(pageMode==="custom"&&styleReference){body.append("style_reference",styleReference);body.append("character_manifest",JSON.stringify(readyCharacters.map(item=>({name:item.name.trim(),description:item.description.trim(),file_count:item.files.length}))));readyCharacters.forEach(item=>item.files.forEach(file=>body.append("character_references",file)))}setJob({id:"",status:"queued",stage:"正在提交任务",progress:1});try{const r=await fetch(`${API}/api/jobs`,{method:"POST",body});const data=await r.json();if(!r.ok)throw new Error(data.detail||"提交失败");setJob(data);loadHistory();poll(data.id)}catch(err){setJob(null);setMessage(err instanceof Error?err.message:"无法连接后端")}};
 const save=async()=>{try{const r=await fetch(`${API}/api/config`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(config)});const data=await r.json();if(!r.ok)throw new Error(data.detail||"保存失败");setConfig(data);setConnectionOk(true);setConnectionMessage("设置已保存在本机")}catch(err){setConnectionOk(false);setConnectionMessage(err instanceof Error?err.message:"保存失败，请检查后端连接")}};
 const chooseOutputDirectory=async()=>{setConnectionOk(null);setConnectionMessage("正在打开文件夹选择器…");try{const response=await fetch(`${API}/api/config/select-output-directory`,{method:"POST"});const data=await response.json();if(!response.ok)throw new Error(data.detail||"无法打开文件夹选择器");if(data.cancelled){setConnectionMessage("已取消选择输出目录");return}setConfig(current=>({...current,output_dir:String(data.path||"")}));setConnectionMessage(data.path?`已选择输出目录：${data.path}`:"未选择输出目录")}catch(err){setConnectionOk(false);setConnectionMessage(err instanceof Error?err.message:"选择输出目录失败")}};
 const test=async()=>{setTesting(true);setConnectionMessage("正在测试 GPT-5、GPT Image 2 和语音服务…");setConnectionOk(null);try{const r=await fetch(`${API}/api/config/test`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(config)});const d=await r.json().catch(()=>null);if(!r.ok)throw new Error(d?.detail||`测试接口返回 HTTP ${r.status}`);const messages=[d?.openlux?.message,d?.image?.message,d?.tts?.message].filter(Boolean);if(messages.length!==3)throw new Error("测试接口返回的数据不完整");const ok=Boolean(d.openlux?.ok&&d.image?.ok&&d.tts?.ok);setConnectionOk(ok);setConnectionMessage(messages.join("；"))}catch(err){setConnectionOk(false);setConnectionMessage(err instanceof Error?err.message:"测试失败，请检查后端连接")}finally{setTesting(false)}};
 const rerender=async(source:Job)=>{setMessage("");setDetailActionMessage("");try{const r=await fetch(`${API}/api/jobs/${source.id}/rerender`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({})});const data=await r.json();if(!r.ok)throw new Error(data.detail||"重新渲染提交失败");setJob(data);setDetailJobId(null);setPreviewImage(null);loadHistory();poll(data.id)}catch(err){const text=err instanceof Error?err.message:"重新渲染失败";setMessage(text);setDetailActionMessage(text)}};
 const retryFailed=async(source:Job)=>{setMessage("");try{const r=await fetch(`${API}/api/jobs/${source.id}/retry`,{method:"POST"});const data=await r.json();if(!r.ok)throw new Error(data.detail||"继续任务失败");setJob(data);loadHistory();poll(data.id)}catch(err){setMessage(err instanceof Error?err.message:"继续任务失败")}};
 const cancelTask=async(source:Job)=>{if(!window.confirm(`确定取消“${source.task_name||source.id}”吗？已完成的断点会保留。`))return;setMessage("");try{const r=await fetch(`${API}/api/jobs/${source.id}/cancel`,{method:"POST"});const data=await r.json();if(!r.ok)throw new Error(data.detail||"取消失败");if(timer.current)clearInterval(timer.current);setJob(data);setMessage("任务已取消，已完成的断点仍保留在历史记录中");loadHistory()}catch(err){setMessage(err instanceof Error?err.message:"取消任务失败")}};
 const deleteHistory=async(source:Job)=>{if(["queued","running"].includes(source.status))return setMessage("排队中或制作中的任务请先取消，再删除历史");if(!window.confirm(`确定删除“${source.task_name||source.id}”吗？历史素材、生成图片和成片都会被删除。`))return;setMessage("");try{const response=await fetch(`${API}/api/jobs/${source.id}`,{method:"DELETE"});const data=await response.json();if(!response.ok)throw new Error(data.detail||"删除历史失败");if(detailJobId===source.id){setDetailJobId(null);setDetailJob(null);setDetailParameters(null);setGallery([]);setPreviewImage(null);setAssetPreview(null)}if(job?.id===source.id)setJob(null);setMessage(data.output_deleted===false?"历史已删除，但输出目录中的成片未能删除":"历史任务已删除");loadHistory()}catch(err){setMessage(err instanceof Error?err.message:"删除历史失败")}};
 const assetFile=async(asset:InputAsset)=>{const response=await fetch(`${API}${asset.url}`);if(!response.ok)throw new Error(`无法读取历史素材：${asset.name}`);return new File([await response.blob()],asset.name,{type:asset.content_type||"application/octet-stream"})};
 const restoreParameters=async(source:Job)=>{setRestoringJobId(source.id);setMessage("");try{const response=await fetch(`${API}/api/jobs/${source.id}/parameters`);const data:JobParameters=await response.json();if(!response.ok)throw new Error((data as unknown as {detail?:string}).detail||"读取历史参数失败");const restoredReference=data.reference?await assetFile(data.reference):null;if(!restoredReference)throw new Error("该历史任务缺少参考音频，不能完整复用");const restoredStyle=data.style_reference?await assetFile(data.style_reference):null;const restoredCharacters=await Promise.all((data.characters||[]).map(async(item,index)=>({id:`restored-${source.id}-${index}`,name:item.name,description:item.description,files:await Promise.all(item.images.map(assetFile))})));setCopy(data.copy);setReference(restoredReference);setVoiceSource("upload");setSelectedVoiceId("");setPageMode(data.reference_mode);setStyle(data.style);setAspectRatio(aspectRatioOptions.some(item=>item.value===data.aspect_ratio)?data.aspect_ratio:"16:9");setScenesPerImage(Math.max(1,Math.min(4,data.scenes_per_image||1)));setTaskName(data.task_name);setPenText(data.pen_text);setIncludeKeyText(data.include_key_text);setIncludeSubtitles(data.include_subtitles);setStrokeDetail(data.stroke_detail);setStyleReference(restoredStyle);setCharacters(restoredCharacters.length?restoredCharacters:[{id:`character-${Date.now()}`,name:"人物 1",description:"",files:[]}]);setJob(source);if(["queued","running"].includes(source.status))poll(source.id);setDetailJobId(null);setPreviewImage(null);setMessage(`已将“${source.task_name||source.id}”的设置和素材填入制作页`);document.querySelector(".workspace")?.scrollIntoView({behavior:"smooth",block:"start"})}catch(err){setMessage(err instanceof Error?err.message:"复用历史任务失败")}finally{setRestoringJobId(null)}};
 const openTaskDetail=(source:Job)=>{setDetailJob(source);setDetailJobId(source.id);setDetailParameters(null);setGallery([]);setPreviewImage(null);setAssetPreview(null);setSelectedGalleryPage(null);setPromptDraft("");setDetailActionMessage("");setDetailLoading(true)};
 const selectGalleryPrompt=(image:GalleryItem)=>{setSelectedGalleryPage(image.page);setPromptDraft(image.prompt||"");setDetailActionMessage("")};
 const regenerateImage=async()=>{if(!detailJob||selectedGalleryPage===null)return;setRegeneratingPage(selectedGalleryPage);setDetailActionMessage("");try{const response=await fetch(`${API}/api/jobs/${detailJob.id}/boards/${selectedGalleryPage}/regenerate`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({prompt:promptDraft})});const data=await response.json();if(!response.ok)throw new Error(data.detail||"图片重生成提交失败");setDetailJob(data);setJob(data);setDetailActionMessage(`第 ${selectedGalleryPage} 张图片已进入重生成队列`);loadHistory();poll(data.id)}catch(err){setDetailActionMessage(err instanceof Error?err.message:"图片重生成失败")}finally{setRegeneratingPage(null)}};
 useEffect(()=>{if(!detailJobId)return;let active=true;const load=async()=>{try{const[jobResponse,galleryResponse,parametersResponse]=await Promise.all([fetch(`${API}/api/jobs/${detailJobId}`),fetch(`${API}/api/jobs/${detailJobId}/gallery`),fetch(`${API}/api/jobs/${detailJobId}/parameters`)]);if(!jobResponse.ok||!galleryResponse.ok||!parametersResponse.ok)throw new Error();const[nextJob,nextGallery,nextParameters]=await Promise.all([jobResponse.json(),galleryResponse.json(),parametersResponse.json()]);if(active){const items:GalleryItem[]=nextGallery.items||[];setDetailJob(nextJob);setGallery(items);setSelectedGalleryPage(current=>{if(current!==null&&items.some(image=>image.page===current))return current;const first=items[0];setPromptDraft(first?.prompt||"");return first?.page??null});setDetailParameters(nextParameters);setDetailLoading(false)}}catch{if(active)setDetailLoading(false)}};load();const interval=setInterval(load,2200);const onKey=(event:KeyboardEvent)=>{if(event.key==="Escape"){setPreviewImage(current=>current?null:current);setAssetPreview(null)}};window.addEventListener("keydown",onKey);return()=>{active=false;clearInterval(interval);window.removeEventListener("keydown",onKey)}},[detailJobId]);
 useEffect(()=>{if(previewImage)selectGalleryPrompt(previewImage)},[previewImage]);
 useEffect(()=>{if(!previewImage)return;const onKey=(event:KeyboardEvent)=>{if(event.key!=="ArrowLeft"&&event.key!=="ArrowRight")return;event.preventDefault();const current=gallery.findIndex(item=>item.name===previewImage.name);const nextIndex=current+(event.key==="ArrowLeft"?-1:1);const next=gallery[nextIndex];if(next)setPreviewImage(next)};window.addEventListener("keydown",onKey);return()=>window.removeEventListener("keydown",onKey)},[previewImage,gallery]);
 const shownJob=job||sharedJob;const showingShared=!job&&!!sharedJob;const selectedGalleryImage=selectedGalleryPage===null?null:gallery.find(image=>image.page===selectedGalleryPage)||null;
 return <main className="shell">
  <header className="topbar"><div className="brand"><span className="brandMark"><img src="/brand-mark.png" alt=""/></span><span>有温度出品</span></div><nav className="pageSwitch" aria-label="制作页面"><button type="button" className={pageMode==="standard"?"active":""} onClick={()=>setPageMode("standard")}>标准制作</button><button type="button" className={pageMode==="custom"?"active":""} onClick={()=>setPageMode("custom")}>自定义参考</button><button type="button" className={pageMode==="infographic"?"active infographicActive":""} onClick={()=>setPageMode("infographic")}>动态信息图</button></nav><nav className="libraryQuickNav" aria-label="库和设置"><a href="/image-generator">单图生成</a><a href="/voices">音色库</a><a href="/styles">画风库</a><a href="/tts">IndexTTS</a></nav><button className="ghost" onClick={()=>setSettingsOpen(!settingsOpen)}>⚙ API 设置</button></header>
  <section className={`hero ${pageMode==="infographic"?"infographicHero":""}`}><p className="eyebrow">{pageMode==="custom"?"参考声音 × 文案 × 自定义视觉":pageMode==="infographic"?"AI 文案分析 × 动态知识卡片":"参考声音 × 一段文案"}</p><h1>{pageMode==="custom"?"让你的画风和人物，贯穿每一幕。":pageMode==="infographic"?"把观点，变成会讲故事的信息图。":"把你的表达，画成一支会说话的白板视频。"}</h1><p className="subtitle">{pageMode==="custom"?"上传风格参考图与多个人物参考，自动生成角色一致的手绘视频。":pageMode==="infographic"?"自动提炼章节、重点与递进论据，生成国风插画和随旁白逐项展开的知识卡片。":"克隆参考音色，自动拆分分镜、生成插画、绘制笔迹并合成视频。"}</p></section>
  {settingsOpen&&<section id="api-settings" className="settings panel"><Title n="01" title="连接服务" note="密钥仅保存在本机后端"/><div className="settingsGrid">
   <label>OpenLux API Key<input type="password" placeholder={config.has_api_key?"已保存，留空则不修改":"OpenLux API Key"} value={config.api_key.includes("••••")?"":config.api_key} onChange={e=>setConfig({...config,api_key:e.target.value})}/></label>
   <label>OpenLux 接口地址<input value={config.base_url} onChange={e=>setConfig({...config,base_url:e.target.value})}/></label><label>文本模型<input placeholder="gpt-5" value={config.text_model} onChange={e=>setConfig({...config,text_model:e.target.value})}/></label><label>图片模型<input placeholder="gpt-image-2" value={config.image_model} onChange={e=>setConfig({...config,image_model:e.target.value})}/></label><label>图片接口地址<input value={config.image_base_url} onChange={e=>setConfig({...config,image_base_url:e.target.value})} placeholder="可留空，与上方接口地址相同"/></label><label>图片 API Key<input type="password" placeholder={config.has_image_api_key?"已保存，留空则不修改":"留空则使用上方 Key"} value={(config.image_api_key||"").includes("••••")?"":(config.image_api_key||"")} onChange={e=>setConfig({...config,image_api_key:e.target.value})}/></label><label>语音节点 1<input value={config.tts_url} onChange={e=>setConfig({...config,tts_url:e.target.value})}/></label><label>语音节点 2<input value={config.tts_url_2} onChange={e=>setConfig({...config,tts_url_2:e.target.value})} placeholder="可留空，仅使用一个节点"/></label><label>语音接口类型<select value={config.tts_mode} onChange={e=>setConfig({...config,tts_mode:e.target.value})}><option value="gradio">IndexTTS Gradio（7860）</option><option value="fastapi">IndexTTS API（8000）</option></select></label><label className="outputDirField"><span>视频输出目录</span><div className="outputDirPicker"><input value={config.output_dir} onChange={e=>setConfig({...config,output_dir:e.target.value})} placeholder="留空则保存在任务历史目录"/><button type="button" className="secondary small" onClick={chooseOutputDirectory}>选择文件夹</button></div><small>macOS 可打开系统文件夹选择器；也可以手动填写绝对路径。只复制最终 MP4，中间素材仍保存在本机历史目录</small></label>
  </div>{health&&<div className="serviceSummary"><strong>局域网共享队列</strong><span>语音 {health.queues.voice.concurrency} 路 · 模型 {health.queues.model.concurrency} 路 · 本地渲染 · 任务断点自动保存</span><div>{health.queues.voice.nodes.map(node=><i key={node.index} className={node.active?"busy":"idle"}>节点 {node.index} · {node.active?"工作中":"空闲"}</i>)}</div></div>}<div className="actions"><button className="secondary" onClick={test} disabled={testing}>{testing?"测试中…":"测试连接"}</button><button className="primary small" onClick={save}>保存设置</button></div>{connectionMessage&&<p className={`message connectionMessage ${connectionOk===true?"success":connectionOk===false?"error":""}`}>{connectionMessage}</p>}</section>}
  <form className="workspace" onSubmit={create}><section className="panel inputPanel"><Title n="01" title="提供素材" note="两项就够了"/>
   <VoicePicker source={voiceSource} voices={voices} selectedVoiceId={selectedVoiceId} reference={reference} loading={voiceLoading} onSourceChange={source=>{setVoiceSource(source);setSelectedVoiceId("");setReference(null)}} onFile={onFile} onSelect={selectVoice}/>
   <label className="copyLabel"><span>视频文案</span><em>{copy.length} 字</em></label><textarea value={copy} onChange={e=>setCopy(e.target.value)} placeholder="粘贴你想讲的内容。系统会按口播节奏自动拆分场景……"/>
   {pageMode==="infographic"?<><section className="infographicIntro"><div className="infographicPreview"><span>文章结构</span><strong>大纲 → 章节 → 论证</strong><i>01</i><p>先理解全文，再决定是否需要总览页</p><i>02</i><p>章节标题持续保留，内部可有多页</p><i>03</i><p>语义进入下一部分时才切换章节</p></div><div><b>通用内容架构</b><h3>动态信息图解说</h3><p>根据文案选择总览、流程、对比、层级、因果、循环、时间线、中心聚焦或总结版式，不再固定三张卡片。</p><ul><li>画面文字保持短小，不放大段解释</li><li>插画自然融入构图，并带独立入场动画</li><li>完全不显示画手，字幕可以在成片设置中开关</li></ul></div></section><div className="styleHeading"><strong>画面风格</strong><span>与标准制作共用同一套风格，可自由选择</span></div><div className="stylePicker">{styleOptions.map(item=><button type="button" key={item.name} className={`styleCard ${item.badge?"featured":""} ${style===item.name?"selected":""}`} onClick={()=>setStyle(item.name)} aria-pressed={style===item.name}><span className="stylePreview"><img src={item.image} alt={`${item.name}预览`}/>{item.badge&&<em>{item.badge}</em>}<i>{style===item.name?"✓ 已选择":"选择"}</i></span><strong>{item.name}</strong><small>{item.desc}</small></button>)}</div></>:pageMode==="standard"?<><div className="styleHeading"><strong>画面风格</strong><span>点击预览图选择，生成结果会严格遵循对应视觉配方</span></div><div className="stylePicker">{styleOptions.map(item=><button type="button" key={item.name} className={`styleCard ${item.badge?"featured":""} ${style===item.name?"selected":""}`} onClick={()=>setStyle(item.name)} aria-pressed={style===item.name}><span className="stylePreview"><img src={item.image} alt={`${item.name}预览`}/>{item.badge&&<em>{item.badge}</em>}<i>{style===item.name?"✓ 已选择":"选择"}</i></span><strong>{item.name}</strong><small>{item.desc}</small></button>)}</div></>:<section className="referenceBuilder"><div className="styleHeading"><strong>自定义参考</strong><span>风格图控制画风，人物组控制角色一致性</span></div><label className={`visualDrop ${styleReference?"ready":""}`}><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setStyleReference(e.target.files?.[0]||null)}/><span>风格参考图</span><strong>{styleReference?styleReference.name:"点击上传一张风格图"}</strong><small>只参考配色、线条、材质与构图，不复制其中人物</small></label><div className="characterHeading"><div><strong>人物参考</strong><span>每个人物可上传 1–3 张不同角度图片</span></div><button type="button" onClick={addCharacter} disabled={characters.length>=5}>＋ 添加人物</button></div><div className="characterList">{characters.map((item,index)=><article className="characterCard" key={item.id}><div className="characterTop"><b>人物 {index+1}</b><button type="button" onClick={()=>removeCharacter(item.id)} disabled={characters.length===1}>删除</button></div><div className="characterFields"><label>人物名称<input maxLength={20} value={item.name} onChange={e=>updateCharacter(item.id,{name:e.target.value})} placeholder="例如：小昌"/></label><label>身份或外观说明<input maxLength={80} value={item.description} onChange={e=>updateCharacter(item.id,{description:e.target.value})} placeholder="例如：短发青年，黑色外套"/></label></div><label className={`characterUpload ${item.files.length?"ready":""}`}><input type="file" multiple accept="image/png,image/jpeg,image/webp" onChange={e=>updateCharacter(item.id,{files:Array.from(e.target.files||[]).slice(0,3)})}/><strong>{item.files.length?`已选择 ${item.files.length} 张参考图`:"上传人物参考图"}</strong><small>{item.files.length?item.files.map(file=>file.name).join("、"):"推荐正面、侧面、全身照，最多 3 张"}</small></label></article>)}</div><p className="referenceTip">最多添加 5 个人物。系统会按人物名称与文案关系，决定每个分镜出现谁。</p></section>}
   {pageMode==="custom"&&(styleReference||characters.some(item=>item.files.length))&&<section className="referenceMediaPreview"><div className="referencePreviewHeading"><strong>已选择的参考素材</strong><span>点击图片放大查看，复用历史任务后也可正常打开</span></div>{styleReference&&<article><div><b>风格参考图</b><small>{styleReference.name}</small></div><FileThumbnail file={styleReference} label="放大风格参考图" onOpen={()=>setInputPreviewFile(styleReference)}/><label className="replaceUpload">重新选择<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setStyleReference(e.target.files?.[0]||null)}/></label></article>}{characters.filter(item=>item.files.length).map(item=><article key={`preview-${item.id}`}><div><b>{item.name||"未命名人物"}</b><small>{item.files.length} 张人物参考图</small></div><div className="referenceThumbs">{item.files.map((file,index)=><FileThumbnail key={`${file.name}-${index}`} file={file} label={`放大${item.name}参考图 ${index+1}`} onOpen={()=>setInputPreviewFile(file)}/>)}</div><label className="replaceUpload">重新选择 1–3 张<input type="file" multiple accept="image/png,image/jpeg,image/webp" onChange={e=>updateCharacter(item.id,{files:Array.from(e.target.files||[]).slice(0,3)})}/></label></article>)}</section>}
  </section>
  <div className="rightStack">
   <section className="panel controlPanel">
    <div className="controlCaption"><strong>成片设置</strong><span>仅保存在当前电脑浏览器</span></div>
    <label className="taskNameField">任务名<input maxLength={30} value={taskName} onChange={e=>setTaskName(e.target.value)} placeholder="留空则自动使用文案前 15 个字"/><small>历史记录显示：{taskName.trim()||copy.replace(/\s+/g,"").slice(0,15)||"等待输入文案"}</small></label>
    <label className="aspectRatioField">视频比例<select value={aspectRatio} onChange={e=>setAspectRatio(e.target.value)}>{aspectRatioOptions.map(item=><option key={item.value} value={item.value}>{item.label}</option>)}</select><small>{aspectRatioOptions.find(item=>item.value===aspectRatio)?.note||"输出视频画布比例"} · 会同步调整插画和最终 MP4</small></label>
    {pageMode==="infographic"?<div className="infographicSettings"><div><strong>语义时间轴</strong><span>每个元素绑定真实旁白，讲到才出现</span></div><div><strong>智能结构</strong><span>自动选择对比、时间轴、层级、因果、案例或总结</span></div><div><strong>文字安全</strong><span>标题与论点由程序排版，不让图片模型生成中文</span></div></div>:<div className="styleRow"><label>每张图包含几个分镜<select value={scenesPerImage} onChange={e=>setScenesPerImage(Number(e.target.value))}><option value={1}>1 个分镜（画面最大）</option><option value={2}>2 个分镜（推荐）</option><option value={3}>3 个分镜</option><option value={4}>4 个分镜（最省图片）</option></select></label><label>笔身文字 / 媒体账号名<input maxLength={12} value={penText} onChange={e=>setPenText(e.target.value)} placeholder="例如：你的账号名"/></label><div className="estimate"><span>文案结构 · 图片上限</span><strong>约 {Math.max(1,Math.round(estimateMinutes(copy)))} 分钟 · 最多 {Math.ceil(estimateSceneCount(copy)/scenesPerImage)} 张</strong></div></div>}
    {pageMode!=="infographic"&&<label className="subtitleToggle"><input type="checkbox" checked={includeKeyText} onChange={e=>setIncludeKeyText(e.target.checked)}/><span><strong>画面重点文字</strong><small>{includeKeyText?"每个分镜显示一条重点短语":"只保留插画，不添加重点词"}</small></span></label>}
    <label className="subtitleToggle"><input type="checkbox" checked={includeSubtitles} onChange={e=>setIncludeSubtitles(e.target.checked)}/><span><strong>生成字幕</strong><small>{includeSubtitles?"成片会烧录中文字幕":"只保留画面和配音"}</small></span></label>
    {pageMode!=="infographic"&&<div className="renderSetting compact"><div><strong>线条绘制量</strong><span>越多越完整，画手动作也越密集</span></div><select value={strokeDetail} onChange={e=>setStrokeDetail(e.target.value)}><option value="light">精简 · 24 条</option><option value="standard">标准 · 48 条</option><option value="detailed">丰富 · 96 条（推荐）</option><option value="full">完整 · 全部线条</option></select></div>}
    <button className="primary create" disabled={!!job&&!["done","error","cancelled"].includes(job.status)}>{job&&!["done","error","cancelled"].includes(job.status)?"正在制作…":"开始生成视频 →"}</button>{message&&<p className={`message ${message.startsWith("已复现")||message.startsWith("任务已取消")?"successMessage":""}`}>{message}</p>}
   </section>
   <aside className="panel resultPanel"><Title n="02" title="制作进度" note="自动完成全部步骤"/>{!shownJob?<div className="emptyState"><div className="paper"><i/><i/><i/></div><h3>视频将在这里出现</h3><p>上传声音与文案，然后点击开始生成。</p></div>:<div className="jobState">{showingShared&&<p className="sharedTask"><span>局域网共享任务</span><strong>{shownJob.client_ip||"未知 IP"}</strong></p>}<div className={`statusOrb ${shownJob.status}`}><span>{shownJob.status==="done"?"✓":shownJob.status==="error"?"!":shownJob.status==="cancelled"?"×":"✦"}</span></div><h3>{shownJob.stage}</h3><div className="progress"><i style={{width:`${shownJob.progress}%`}}/></div><p>{shownJob.progress}%{shownJob.scenes?` · ${shownJob.scenes} 幕${shownJob.boards?` / ${shownJob.boards} 张图`:""} · ${shownJob.duration?.toFixed(1)} 秒`:""}</p><div className="timingPanel"><div className="timingTotal"><span>总耗时</span><strong>{formatDuration(shownJob.total_elapsed||0)}</strong>{shownJob.status==="running"&&<em>当前环节 {formatDuration(shownJob.current_elapsed||0)}</em>}</div>{shownJob.timings&&Object.entries(shownJob.timings).map(([key,item])=><div className={`timingRow ${item.running?"running":""}`} key={key}><span>{item.running?"● ":"✓ "}{item.label}</span><strong>{formatDuration(item.seconds)}</strong></div>)}</div>{shownJob.error&&<pre>{shownJob.error}</pre>}{Boolean(shownJob.image_count)&&<button type="button" className="galleryButton" onClick={()=>openTaskDetail(shownJob)}>查看已生成的 {shownJob.image_count} 张图片</button>}{shownJob.can_cancel&&<button type="button" className="cancelButton" onClick={()=>cancelTask(shownJob)}>取消任务</button>}{shownJob.status==="error"&&shownJob.can_retry&&<button type="button" className="retryButton" onClick={()=>retryFailed(shownJob)}>重试并继续任务</button>}{shownJob.status==="done"&&shownJob.result_url&&<><video controls src={`${API}${shownJob.result_url}`}/><a className="download" href={`${API}${shownJob.result_url}`}>下载 MP4</a></>}</div>}{pageMode==="infographic"?<ol className="steps infographicSteps"><li>克隆参考音色</li><li>生成短语时间表</li><li>梳理中心句与关键词</li><li>制作 Remotion PPT</li><li>按 PPT 生成插图</li><li>合成音画成片</li></ol>:<ol className="steps"><li>克隆参考音色</li><li>拆分文案分镜</li><li>生成统一插画</li><li>绘制白板动画</li><li>合成音画成片</li></ol>}</aside>
  </div>
 </form>
 <section className="historyControls panel"><label className="historySearch"><span>搜索生成历史</span><input value={historySearch} onChange={event=>{setHistorySearch(event.target.value);setHistoryPage(1)}} placeholder="按任务名、文案、画风、状态或任务 ID 搜索" /></label><span className="historyTotal">共 {historyTotal} 条记录</span><div className="historyPagination"><button type="button" className="secondary small" disabled={historyPage<=1} onClick={()=>setHistoryPage(historyPage-1)}>上一页</button><span>第 {historyPage} / {historyPages} 页</span><button type="button" className="secondary small" disabled={historyPage>=historyPages} onClick={()=>setHistoryPage(historyPage+1)}>下一页</button></div></section>
  <section className="panel historyPanel"><Title n="03" title="生成历史" note="点击任务查看图片、参数与成片"/>{history.length?<div className="historyList">{history.map(item=><article key={item.id} tabIndex={0} onClick={()=>openTaskDetail(item)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();openTaskDetail(item)}}}><div><strong><em>{item.job_type==="rerender"?"重新渲染":item.job_type==="infographic"?"动态信息图":"视频生成"}</em>{item.task_name||`未命名任务-${item.id.slice(-4)}`}</strong><span>{formatDate(item.created_at)} · {item.style||"默认风格"} · {item.stage}</span><span className="historyMeta">笔身文字：{item.pen_text||"未设置"} · IP：{item.client_ip||"未知"}</span></div><div><span className="imageCount">{item.image_count?`${item.image_count} 张图片`:"暂无图片"}</span>{item.can_cancel&&<button type="button" className="cancelHistory" onClick={event=>{event.stopPropagation();cancelTask(item)}}>取消</button>}{item.status!=="queued"&&item.status!=="running"&&<><button type="button" className="editHistory" onClick={event=>{event.stopPropagation();restoreParameters(item)}}>编辑</button><button type="button" className="deleteHistory" onClick={event=>{event.stopPropagation();deleteHistory(item)}}>删除</button></>}{item.status==="done"&&item.result_url&&<a className="downloadHistory" href={`${API}${item.result_url}`} download onClick={event=>event.stopPropagation()}>下载成片</a>}<button type="button" className="viewHistory" onClick={event=>{event.stopPropagation();openTaskDetail(item)}}>查看详情</button></div></article>)}</div>:<p className="historyEmpty">完成一次视频制作后，记录会显示在这里。</p>}</section>
  {detailJobId&&detailJob&&<div className="taskDetailOverlay" role="presentation" onMouseDown={event=>{if(event.target===event.currentTarget){setDetailJobId(null);setPreviewImage(null)}}}><section className="taskDetailDialog" role="dialog" aria-modal="true" aria-label="任务详情"><header><div><span className={`taskStatus ${detailJob.status}`}>{statusLabel(detailJob.status)}</span><h2>{detailJob.task_name||detailJob.id}</h2><p>{detailJob.stage} · {detailJob.progress}% · {formatDate(detailJob.created_at)}</p></div><button type="button" className="detailClose" onClick={()=>{setDetailJobId(null);setPreviewImage(null)}} aria-label="关闭">×</button></header><div className="taskDetailBody"><section className="detailGallery"><div className="detailSectionTitle"><div><strong>生成图片</strong><span>{gallery.length?`共 ${gallery.length} 张，点击图片放大查看`:detailLoading?"正在读取图片…":"该任务尚未生成图片"}</span></div>{["queued","running"].includes(detailJob.status)&&<i>生成中，图片会自动出现</i>}</div>{gallery.length?<div className="galleryGrid">{gallery.map(image=><button type="button" key={image.name} onClick={()=>setPreviewImage(image)}><img src={`${API}${image.url}`} alt={`第 ${image.page} 张生成图片`}/><span>第 {image.page} 张</span></button>)}</div>:<div className="galleryEmpty"><b>{detailLoading?"正在加载…":"暂无可查看图片"}</b><span>{detailJob.status==="error"?"可以从断点继续任务":"图片生成后会显示在这里"}</span></div>}</section><aside className="detailSidebar"><section><h3>本次参数</h3>{detailParameters?<dl><div><dt>制作方式</dt><dd>{modeLabel(detailParameters.reference_mode)}</dd></div><div><dt>画面风格</dt><dd>{detailParameters.style}</dd></div><div><dt>字幕</dt><dd>{detailParameters.include_subtitles?"已添加":"未添加"}</dd></div>{detailParameters.reference_mode!=="infographic"&&<><div><dt>每张分镜</dt><dd>{detailParameters.scenes_per_image} 幕</dd></div><div><dt>画面重点文字</dt><dd>{detailParameters.include_key_text?"显示":"不显示"}</dd></div></>}<div><dt>参考音频</dt><dd>{detailParameters.reference?.name||"缺失"}</dd></div>{detailParameters.characters.length>0&&<div><dt>人物参考</dt><dd>{detailParameters.characters.length} 组</dd></div>}</dl>:<p>正在读取参数…</p>}</section>{detailJob.error&&<section className="detailError"><h3>错误信息</h3><p>{detailJob.error}</p></section>}<div className="detailActions"><button type="button" className="reuseTask" disabled={restoringJobId===detailJob.id} onClick={()=>restoreParameters(detailJob)}>{restoringJobId===detailJob.id?"正在读取素材…":"复用本次设置和素材"}</button>{detailJob.can_cancel&&<button type="button" className="cancelTaskDetail" onClick={()=>cancelTask(detailJob)}>取消任务</button>}{detailJob.status==="error"&&detailJob.can_retry&&<button type="button" className="retryTaskDetail" onClick={()=>retryFailed(detailJob)}>从断点继续</button>}{detailJob.status==="done"&&detailJob.result_url&&<a href={`${API}${detailJob.result_url}`}>下载成片</a>}</div></aside></div>{detailJob.status==="done"&&detailJob.result_url&&<div className="detailVideo"><strong>最终成片</strong><video controls src={`${API}${detailJob.result_url}`}/></div>}</section>{previewImage&&<div className="imageLightbox" role="dialog" aria-modal="true" aria-label={`第 ${previewImage.page} 张图片`} onMouseDown={event=>{if(event.target===event.currentTarget)setPreviewImage(null)}}><button type="button" onClick={()=>setPreviewImage(null)}>×</button><button type="button" className="imageLightboxNav previous" disabled={gallery.findIndex(item=>item.name===previewImage.name)<=0} onClick={()=>{const current=gallery.findIndex(item=>item.name===previewImage.name);if(current>0)setPreviewImage(gallery[current-1])}} aria-label="上一张">‹</button><img src={`${API}${previewImage.url}`} alt={`第 ${previewImage.page} 张生成图片大图`}/><button type="button" className="imageLightboxNav next" disabled={gallery.findIndex(item=>item.name===previewImage.name)<0||gallery.findIndex(item=>item.name===previewImage.name)>=gallery.length-1} onClick={()=>{const current=gallery.findIndex(item=>item.name===previewImage.name);if(current>=0&&current<gallery.length-1)setPreviewImage(gallery[current+1])}} aria-label="下一张">›</button><span>第 {previewImage.page} 张</span></div>}</div>}
  {detailJobId&&detailJob&&detailParameters&&<aside className="detailMediaDock"><header><div><strong>本次使用的素材</strong><span>音频可播放，参考图可放大</span></div><button type="button" onClick={()=>setDetailJobId(null)}>×</button></header>{detailParameters.reference&&<div className="detailAudio"><b>{detailParameters.reference.name}</b><audio controls preload="metadata" src={`${API}${detailParameters.reference.url}`}/></div>}{detailParameters.style_reference&&<div className="detailReferenceGroup"><b>风格参考图</b><button type="button" onClick={()=>setAssetPreview({src:`${API}${detailParameters.style_reference!.url}`,label:"风格参考图"})}><img src={`${API}${detailParameters.style_reference.url}`} alt="风格参考图"/><span>点击放大</span></button></div>}{detailParameters.characters.map((character,index)=><div className="detailReferenceGroup" key={`${character.name}-${index}`}><b>{character.name}</b><div>{character.images.map((image,imageIndex)=><button type="button" key={image.url} onClick={()=>setAssetPreview({src:`${API}${image.url}`,label:`${character.name}参考图 ${imageIndex+1}`})}><img src={`${API}${image.url}`} alt={`${character.name}参考图 ${imageIndex+1}`}/><span>放大</span></button>)}</div></div>)}{detailJob.status==="done"&&detailJob.can_rerender&&<button type="button" className="rerenderFromDetail" onClick={()=>rerender(detailJob)}>用当前图片重新渲染成片</button>}</aside>}
  {detailJobId&&detailJob&&selectedGalleryImage&&!previewImage&&<aside className="promptEditorPanel"><header><div><strong>第 {selectedGalleryImage.page} 张图片提示词</strong><span>{selectedGalleryImage.scene_numbers?.length?`对应第 ${selectedGalleryImage.scene_numbers.join("、")} 个场景`:"可修改后只重生成这一张"}</span></div><button type="button" onClick={()=>setSelectedGalleryPage(null)}>×</button></header><textarea value={promptDraft} onChange={event=>setPromptDraft(event.target.value)} placeholder="输入这张图片的生成提示词"/><div className="promptMeta"><span>{promptDraft.length} 字</span><button type="button" disabled={regeneratingPage!==null||detailJob.can_cancel||promptDraft.trim().length<5} onClick={regenerateImage}>{regeneratingPage===selectedGalleryImage.page?"正在提交…":detailJob.can_cancel?"任务执行中":"保存提示词并重新生成"}</button></div>{detailActionMessage&&<p>{detailActionMessage}</p>}</aside>}
  {inputPreviewFile&&<FileLightbox file={inputPreviewFile} onClose={()=>setInputPreviewFile(null)}/>} {assetPreview&&<div className="imageLightbox assetLightbox" role="dialog" aria-modal="true" aria-label={assetPreview.label} onMouseDown={event=>{if(event.target===event.currentTarget)setAssetPreview(null)}}><button type="button" onClick={()=>setAssetPreview(null)}>×</button><img src={assetPreview.src} alt={assetPreview.label}/><span>{assetPreview.label}</span></div>}
  <footer><span>所有素材与历史记录保存在你的电脑上</span><span>IndexTTS 2.5 · GPT-5 · GPT Image 2 · FFmpeg</span></footer>
 </main>}
function Title({n,title,note}:{n:string;title:string;note:string}){return <div className="sectionTitle"><div><span>{n}</span><h2>{title}</h2></div><p>{note}</p></div>}
function formatDuration(value:number){const seconds=Math.max(0,Math.floor(value));const h=Math.floor(seconds/3600);const m=Math.floor((seconds%3600)/60);const s=seconds%60;return h?`${h}时 ${m}分 ${s}秒`:m?`${m}分 ${s}秒`:`${s}秒`}
function formatDate(value?:number){return value?new Date(value*1000).toLocaleString("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}):"刚刚"}
function strokeLabel(value?:string){return({light:"精简线条",standard:"标准线条",detailed:"丰富线条",full:"完整线条"} as Record<string,string>)[value||""]||"丰富线条"}
function statusLabel(value:Job["status"]){return({queued:"排队中",running:"制作中",done:"已完成",error:"失败",cancelled:"已取消"} as Record<Job["status"],string>)[value]}
function modeLabel(value:JobParameters["reference_mode"]){return({standard:"标准制作",custom:"自定义参考",infographic:"动态信息图"} as Record<JobParameters["reference_mode"],string>)[value]}
function aspectRatioLabel(value?:string){return({"16:9":"16:9 横屏","9:16":"9:16 竖屏","1:1":"1:1 方形"} as Record<string,string>)[value||"16:9"]||"16:9 横屏"}
function VoicePicker({source,voices,selectedVoiceId,reference,loading,onSourceChange,onFile,onSelect}:{source:"upload"|"library";voices:Voice[];selectedVoiceId:string;reference:File|null;loading:boolean;onSourceChange:(source:"upload"|"library")=>void;onFile:(event:ChangeEvent<HTMLInputElement>)=>void;onSelect:(voiceId:string)=>void}){const selected=voices.find(item=>item.id===selectedVoiceId);return <section className="voicePickerPanel"><div className="voicePickerHeading"><strong>参考音色</strong><span>{source==="library"?"从本机音色库选择":"上传一段新的参考音频"}</span></div><div className="voiceSourceTabs"><button type="button" className={source==="upload"?"active":""} onClick={()=>onSourceChange("upload")}>上传音频</button><button type="button" className={source==="library"?"active":""} onClick={()=>onSourceChange("library")}>选择音色库</button></div>{source==="upload"?<><label className={`dropzone ${reference?"ready":""}`}><input type="file" accept="audio/*,.wav,.mp3,.m4a,.aac,.flac,.ogg,.webm" onChange={onFile}/><span className="uploadIcon">⌁</span><strong>{reference?reference.name:"上传参考音频"}</strong><small>{reference?`${(reference.size/1024/1024).toFixed(1)} MB · 点击这里可重新选择`:"建议 10–30 秒，单人、无噪声、WAV 最佳"}</small></label>{reference&&<AudioFilePreview file={reference}/>}</>:voices.length?<div className="voiceLibrarySelect"><label>选择已保存的音色<select value={selectedVoiceId} onChange={event=>onSelect(event.target.value)}><option value="">请选择音色</option>{voices.map(voice=><option key={voice.id} value={voice.id}>{voice.name}</option>)}</select></label>{selected&&<><div className="selectedVoiceMeta"><strong>{selected.name}</strong><span>{selected.filename} · {(selected.size||0)/1024/1024<1?`${Math.max(1,Math.round((selected.size||0)/1024))} KB`:`${((selected.size||0)/1024/1024).toFixed(1)} MB`}</span></div><audio controls preload="metadata" src={`${API}/api/voices/${selected.id}/audio`}/></>}{loading&&<small className="voiceLoading">正在读取音色…</small>}</div>:<div className="voiceLibraryEmpty"><strong>音色库还没有音色</strong><span>打开 API 设置 → 音色库，先新增一条音色。</span></div>}</section>}
function VoiceLibraryPanel({voices,onRefresh}:{voices:Voice[];onRefresh:()=>Promise<void>}){const[name,setName]=useState("");const[file,setFile]=useState<File|null>(null);const[busy,setBusy]=useState(false);const[message,setMessage]=useState("");const add=async()=>{if(!file)return setMessage("请先选择音频文件");setBusy(true);setMessage("");try{const body=new FormData();body.append("name",name);body.append("audio",file);const response=await fetch(`${API}/api/voices`,{method:"POST",body});const data=await response.json();if(!response.ok)throw new Error(data.detail||"新增音色失败");setName("");setFile(null);setMessage(`已新增音色“${data.name}”`);await onRefresh()}catch(err){setMessage(err instanceof Error?err.message:"新增音色失败")}finally{setBusy(false)}};const rename=async(voice:Voice)=>{const next=window.prompt("请输入新的音色名称",voice.name)?.trim();if(!next||next===voice.name)return;setBusy(true);setMessage("");try{const response=await fetch(`${API}/api/voices/${voice.id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:next})});const data=await response.json();if(!response.ok)throw new Error(data.detail||"重命名失败");setMessage(`已将音色重命名为“${data.name}”`);await onRefresh()}catch(err){setMessage(err instanceof Error?err.message:"重命名失败")}finally{setBusy(false)}};const remove=async(voice:Voice)=>{if(!window.confirm(`确定删除音色“${voice.name}”吗？已经生成的历史任务不受影响。`))return;setBusy(true);setMessage("");try{const response=await fetch(`${API}/api/voices/${voice.id}`,{method:"DELETE"});const data=await response.json();if(!response.ok)throw new Error(data.detail||"删除音色失败");setMessage(`已删除音色“${voice.name}”`);await onRefresh()}catch(err){setMessage(err instanceof Error?err.message:"删除音色失败")}finally{setBusy(false)}};return <section className="settings panel voiceLibraryPanel"><Title n="02" title="音色库" note="音频只保存在本机"/><div className="voiceLibraryAdd"><label>音色名称<input maxLength={30} value={name} onChange={event=>setName(event.target.value)} placeholder="例如：我的解说音色"/></label><label>参考音频<input type="file" accept="audio/*,.wav,.mp3,.m4a,.aac,.flac,.ogg,.webm" onChange={event=>setFile(event.target.files?.[0]||null)}/><small>{file?file.name:"建议使用 10–30 秒的清晰单人音频"}</small></label><button type="button" className="primary small" onClick={add} disabled={busy}>{busy?"处理中…":"新增音色"}</button></div>{voices.length?<div className="voiceLibraryList">{voices.map(voice=><article key={voice.id}><div><strong>{voice.name}</strong><span>{voice.filename} · {((voice.size||0)/1024/1024).toFixed(1)} MB</span></div><audio controls preload="metadata" src={`${API}/api/voices/${voice.id}/audio`}/><div><button type="button" className="editHistory" onClick={()=>rename(voice)} disabled={busy}>重命名</button><button type="button" className="deleteHistory" onClick={()=>remove(voice)} disabled={busy}>删除</button></div></article>)}</div>:<p className="voiceLibraryEmpty">还没有保存的音色。</p>}{message&&<p className={`message ${message.startsWith("已")?"successMessage":""}`}>{message}</p>}</section>}
function AudioFilePreview({file}:{file:File}){const[url,setUrl]=useState("");useEffect(()=>{const next=URL.createObjectURL(file);setUrl(next);return()=>URL.revokeObjectURL(next)},[file]);return <div className="audioPreview"><div><strong>试听参考音频</strong><span>可拖动进度，点击上方上传区可重新选择</span></div><audio controls preload="metadata" src={url||undefined}/></div>}
function FileThumbnail({file,label,onOpen}:{file:File;label:string;onOpen:()=>void}){const[url,setUrl]=useState("");useEffect(()=>{const next=URL.createObjectURL(file);setUrl(next);return()=>URL.revokeObjectURL(next)},[file]);return <button type="button" className="fileThumbnail" onClick={onOpen} aria-label={label}>{url&&<img src={url} alt=""/>}<span>放大</span></button>}
function FileLightbox({file,onClose}:{file:File;onClose:()=>void}){const[url,setUrl]=useState("");useEffect(()=>{const next=URL.createObjectURL(file);setUrl(next);return()=>URL.revokeObjectURL(next)},[file]);return <div className="imageLightbox assetLightbox" role="dialog" aria-modal="true" aria-label={`查看 ${file.name}`} onMouseDown={event=>{if(event.target===event.currentTarget)onClose()}}><button type="button" onClick={onClose}>×</button>{url&&<img src={url} alt={file.name}/>}<span>{file.name}</span></div>}
